{
  "interface": {
    "mode": "stdin_stdout",
    "signature": "stdin -> stdout"
  },
  "preconditions": [
    {
      "id": "P1",
      "expression": "3 <= n <= 150000",
      "description": "The number of members is between 3 and 150,000."
    },
    {
      "id": "P2",
      "expression": "0 <= m < n * (n - 1) / 2",
      "description": "The number of pairs of friends is less than the total possible pairs."
    },
    {
      "id": "P3",
      "expression": "1 <= ai, bi <= n",
      "description": "Each member is numbered between 1 and n."
    },
    {
      "id": "P4",
      "expression": "ai != bi",
      "description": "No member is a friend with themselves."
    },
    {
      "id": "P5",
      "expression": "Each pair (ai, bi) appears at most once",
      "description": "Each pair of members is listed only once."
    }
  ],
  "postconditions": [
    {
      "id": "Q1",
      "expression": "output == 'YES' or output == 'NO'",
      "description": "The output is either 'YES' or 'NO'."
    }
  ],
  "invariants": [
    {
      "id": "I1",
      "expression": "all(ai in range(1, n + 1) and bi in range(1, n + 1) for ai, bi in friend_pairs)",
      "description": "All friend pairs are within the range of member numbers."
    },
    {
      "id": "I2",
      "expression": "all(ai != bi for ai, bi in friend_pairs)",
      "description": "No member is a friend with themselves."
    },
    {
      "id": "I3",
      "expression": "all(ai != bi for ai, bi in combinations(range(1, n + 1), 2) if (ai, bi) not in friend_pairs and (bi, ai) not in friend_pairs)",
      "description": "All possible pairs of members that are not friends are not listed."
    },
    {
      "id": "I4",
      "expression": "all(all(ai in friends_of[bi] for ai in friends_of[bi]) and all(bi in friends_of[ai] for bi in friends_of[ai]) for ai, friends_of in friends_of_members.items())",
      "description": "Each member's friends list is symmetric."
    },
    {
      "id": "I5",
      "expression": "all(all(ai in friends_of[bi] and bi in friends_of[ai] for ai, bi in combinations(range(1, n + 1), 2) if (ai, bi) not in friend_pairs and (bi, ai) not in friend_pairs) for bi, friends_of in friends_of_members.items())",
      "description": "All possible pairs of members that are not friends are not listed in any member's friends list."
    },
    {
      "id": "I6",
      "expression": "all(all(ai in friends_of[bi] and bi in friends_of[ai] and ai in friends_of[cj] and cj in friends_of[ai] and bi in friends_of[cj] and cj in friends_of[bi] for ai, bi in friend_pairs for cj in range(1, n + 1) if cj != ai and cj != bi) for bi, friends_of in friends_of_members.items())",
      "description": "For every three distinct members (X, Y, Z), if X-Y and Y-Z then also X-Z."
    }
  ]
}
